<?php
require_once __DIR__.'/../includes/functions.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('pages/quizzes.php');verify_csrf();$lessonId=(int)($_POST['lesson_id']??0);$stmt=$pdo->prepare('SELECT id,title FROM lessons WHERE id=? AND is_published=1');$stmt->execute([$lessonId]);$lesson=$stmt->fetch();if(!$lesson)redirect('pages/quizzes.php');$stmt=$pdo->prepare('SELECT id,correct_option,explanation FROM quiz_questions WHERE lesson_id=? ORDER BY id');$stmt->execute([$lessonId]);$questions=$stmt->fetchAll();if(!$questions){flash('warning','This quiz does not have questions yet.');redirect('pages/quizzes.php');}$answers=$_POST['answers']??[];$correct=0;$review=[];foreach($questions as $q){$given=$answers[$q['id']]??'';$ok=is_string($given)&&strtolower($given)===$q['correct_option'];if($ok)$correct++;$review[]=['correct'=>$ok,'explanation'=>$q['explanation']];}$total=count($questions);$percentage=(int)round($correct/$total*100);$stmt=$pdo->prepare('INSERT INTO quiz_attempts(user_id,lesson_id,score,total_questions,percentage) VALUES(?,?,?,?,?)');$stmt->execute([(int)current_user()['id'],$lessonId,$correct,$total,$percentage]);$_SESSION['last_quiz_result']=['lesson'=>$lesson['title'],'correct'=>$correct,'total'=>$total,'percentage'=>$percentage,'review'=>$review];redirect('pages/quiz_result.php');
